      "bn": "সিসিআই (CCI) সরকারি ক্রয় এবং বাজারে উচ্চ বাণিজ্যিক চাহিদা",
      "gu": "સીસીઆઈ (CCI) સરકારી ખરીદી અને માર્કેટ યાર્ડમાં ઊંચી વ્યાપારી માંગ",
      "od": "ସିସିଆଇ (CCI) ସରକାରୀ କ୍ରୟ ଏବଂ ମଣ୍ଡିରେ ଉଚ୍ଚ ବ୍ୟାବସାୟିକ ଚାହିଦା"
