      "ml": "ഗവൺമെന്റ് താങ്ങുവില സംഭരണവും ദേശീയ തലത്തിൽ സ്ഥിരമായ ഭക്ഷ്യ ആവശ്യകതയും",
      "mr": "हमीभावाने शासकीय खरेदी आणि स्थिर अन्नधान्य मागणी",
      "bn": "সরকারি সহায়ক মূল্যে ক্রয় এবং নিরবচ্ছিন্ন খাদ্যশস্যের জাতীয় চাহিদা",
      "gu": "સરકારની ટેકાના ભાવે ખરીદી અને સતત સ્થિર અનાજની માંગ",
      "od": "ସରକାରୀ ଏମଏସପି କ୍ରୟ ଏବଂ ନିରନ୍ତର ଖାଦ୍ୟଶସ୍ୟ ଚାହିଦା"
