      "bn": "ফল আর্মিওয়ার্ম এবং কাণ্ড ছিদ্রকারী পোকার ব্যাপক আক্রমণের ঝুঁকি।",
      "gu": "લશ્કરી ઈયળ (ફોલ આર્મીવોર્મ) અને સાંઠાની ઈયળનો ભારે ઉપદ୍ରવ થવાનું જોખમ.",
