      "hi": "महत्वपूर्ण नमी चरण: घुटने की ऊंचाई (30-35 दिन), नर मंजरी और भुट्टे में दाना भरना। परागण के समय पानी की कमी से भुट्टे खाली रह जाते हैं।",
