      "kn": "ಪ್ರಮುಖ ತೇವಾಂಶ ಹಂತಗಳು: ಮೊಣಕಾಲು ಎತ್ತರ (30-35 ದಿನಗಳು), ಹೂಗೊಂಚಲು ಮತ್ತು ತೆನೆ ತುಂಬುವಿಕೆ. ಪರಾಗಸ್ಪರ್ಶದ ವೇಳೆ ನೀರಿನ ಕೊರತೆಯಾದರೆ ಕಾಳು ಕಟ್ಟುವುದಿಲ್ಲ.",
