      "ta": "திக்கா இலைப்புள்ளி நோய், நீர் தேங்கினால் தண்டு அழுகல் மற்றும் காய்களைத் தாக்கும் வெள்ளை வண்டு புழு.",
      "kn": "ತಿಕ್ಕಾ ಎಲೆಚುಕ್ಕೆ ರೋಗ, ನೀರು ನಿಲ್ಲುವಲ್ಲಿ ಕೊರಳು ಕೊಳೆತ ಮತ್ತು ಕಾಯಿಗಳಿಗೆ ಬಿಳಿ ಗೊಣ್ಣೆಹುಳುವಿನ ಬಾಧೆ.",
      "ml": "ടിക്ക ഇലപ്പുള്ളി രോഗം, നീർക്കെട്ടുള്ള മണ്ണിൽ കടചീയൽ, വേരുതീനി പുഴുക്കളുടെ ആക്രമണം.",
      "mr": "टਿੱಕಾ पानांवरील ठिपके, पाणी साचल्यास खोडकुज आणि हुमणी अळीचा प्रादुर्भाव.",
      "bn": "টিক্কা পাতার দাগ রোগ, জমা জলে কলার রট এবং সাদা গ্রাবের আক্রমণ।",
      "gu": "ટિક્કા પાનના ટપકાંનો રોગ, પાણી ભરાવાથી થડનો સડો અને ધૂણેટી (સફેદ ગ્રીબ) નો ઉપદ્રવ.",
      "od": "ଟିକ୍କା ପତ୍ରଦାଗ ରୋଗ, ଜଳବନ୍ଦୀରେ ମୂଳ ସଢ଼ା ଏବଂ ଧଳା ଶୁଆ ପୋକ ଆକ୍ରମଣ।"
