      "bn": "বেলে ও অনুর্বর জমিতেও টিকে থাকার অসাধারণ ক্ষমতা। তীব্র গরম এবং অনিয়মিত বৃষ্টিতেও নির্ভরযোগ্য ফলন দেয়।",
