      "ta": "நல்ல வடிகால் வசதியுள்ள செம்மண் மற்றும் லேசான வண்டல் மண். ஆழமான ஆணிவேர் அமைப்பு கீழ்மண்ணிலிருந்து நீரையும் சத்துக்களையும் உறிஞ்சும்.",
      "kn": "ಉತ್ತಮ ನೀರು ಬಸಿದು ಹೋಗುವ ಕೆಂಪು ಮರಳು ಮಣ್ಣು ಮತ್ತು ಹಗುರ ಗೋಡು ಮಣ್ಣು. ಆಳವಾದ ತಾಯಿಬೇರು ಕೆಳಗಿನಿಂದ ನೀರು ಮತ್ತು ಪೋಷಕಾಂಶಗಳನ್ನು ಹೀರಿಕೊಳ್ಳುತ್ತದೆ.",
