      "ta": "தண்டு வளரும் பருவத்தில் அதிக மழை அல்லது ஈரப்பதம் தேவை, மற்றும் சணல் ஊறவைத்து நார் பிரிக்க சுத்தமான நீர் அவசியம்.",
