    "soil_guidance": {
      "en": "New alluvial soils along river basins rich in silt and organic matter. Neutral pH 6.2-7.2 promotes long, flexible bast fibers.",
      "te": "నదీ పరివాహక ప్రాంతాల్లోని ఒండ్రు మరియు సిల్ట్ నేలలు (pH 6.2-7.2). ఇవి పొడవైన, మృదువైన నాణ్యమైన నార ఉత్పత్తికి ఎంతో అనుకూలం.",
      "hi": "नदी घाटियों की नई जलोढ़ और गाद युक्त उपजाऊ मिट्टी (pH 6.2-7.2)। यह लंबे और लचीले रेशे के विकास के लिए उत्तम है।",
      "ta": "ஆற்றுப் படுகைகளின் புதிய வண்டல் மற்றும் வண்டல் மண் (pH 6.2-7.2). இது நீளமான, நெகிழ்வான சணல் நார்களை உற்பத்தி செய்ய உதவுகிறது.",
      "kn": "ನದಿ ಪಾತ್ರಗಳ ಮೆಕ್ಕಲು ಮತ್ತು ಹೂಳು ಮಣ್ಣು (pH 6.2-7.2). ಇದು ಉದ್ದವಾದ ಮತ್ತು ನಯವಾದ ಉತ್ತಮ ನಾರು ಉತ್ಪಾದನೆಗೆ ಅತ್ಯುತ್ತಮ.",
      "ml": "നദീതീരങ്ങളിലെ എക്കലും എക്കൽമണ്ണും (pH 6.2-7.2). ഇത് നീളമുള്ളതും വഴക്കമുള്ളതുമായ ചണനാരുകൾ ലഭിക്കാൻ സഹായിക്കുന്നു.",
      "mr": "नदीकाठची नवीन गाळाची जमीन (सामू 6.2-7.2). लांब आणि लवचिक उत्कृष्ट दर्जाच्या तागाच्या धाग्यांसाठी उपयुक्त.",
      "bn": "নদী অববাহিকার নতুন পলি ও এঁটেল দোআঁশ মাটি (pH 6.2-7.2)। এটি দীর্ঘ ও নমনীয় ভালো মানের পাট তন্তুর জন্য আদর্শ।",
      "gu": "નદી કાંઠાની નવી કાંપવાળી અને ફળદ્રુપ ગોરાડુ જમીન (pH 6.2-7.2). લાંબા અને મજબૂત શણના રેસા માટે શ્રેષ્ઠ છે.",
      "od": "ନଦୀ ଅବବାହିକାର ନୂତନ ପଟୁ ଏବଂ ଦୋରସା ମାଟି (pH 6.2-7.2)। ଲମ୍ବା ଏବଂ ନମନୀୟ ଉନ୍ନତ ଝୋଟ ତନ୍ତୁ ପାଇଁ ଉପଯୁକ୍ତ।"
    },
    "water_scheduling": {
      "en": "Demands abundant rainfall or frequent standing moisture during stem elongation, plus clean water for ribbon retting.",
      "te": "కాండం పెరిగే దశలో పుష్కలమైన వర్షపాతం లేదా తేమ అవసరం, అలాగే నార తీయడానికి (రెట్టింగ్) స్వచ్ఛమైన నీరు కావాలి.",
      "hi": "तने की बढ़वार के समय भरपूर वर्षा या नमी की आवश्यकता होती है, साथ ही रेशा सड़ाने (रेटिंग) के लिए स्वच्छ जल चाहिए।",
      "ta": "தண்டு வளரும் பருவத்தில் அதிக மழை அல்லது ஈரப்பதம் தேவை, மற்றும் சணல் ஊறவைத்து நார் பிரிக்க சுத்தமான நீர் அவசியம்.",
      "kn": "ಕಾಂಡದ ಬೆಳವಣಿಗೆಯ ವೇಳೆ ಸಮೃದ್ಧ ಮಳೆ ಅಥವಾ ತೇವಾಂಶ ಬೇಕು, ಹಾಗೂ ನಾರು ಹದಗೊಳಿಸಲು (ರೆಟ್ಟಿಂಗ್) ಶುದ್ಧ ನೀರು ಅಗತ್ಯ.",
      "ml": "തണ്ട് വളരുന്ന സമയത്ത് സമൃദ്ധമായ മഴയും ഈർപ്പവും വേണം, കൂടാതെ ചണം ചീയപ്പിച്ച് നാരെടുക്കാൻ ശുദ്ധജലം ആവശ്യമാണ്.",
      "mr": "खोडाच्या वाढीच्या काळात भरपूर पाऊस किंवा सतत ओलावा लागतो, तसेच धागा काढण्यासाठी (रेटिंग) स्वच्छ पाण्याची गरज असते.",
      "bn": "কাণ্ড বৃদ্ধির সময় প্রচুর বৃষ্টি বা পর্যাপ্ত আর্দ্রতা প্রয়োজন, এবং পাট পচানোর (রেটিং) জন্য পরিষ্কার জলের প্রয়োজন।",
      "gu": "સાંઠો વધવાના સમયે પુષ્કળ વરસાદ કે સતત ભેજ જરૂરી છે, તેમજ શણ કોહવડાવી રેસા છૂટા પાડવા ચોખ્ખું પાણી જોઈએ.",
      "od": "କାଣ୍ଡ ବୃଦ୍ଧି ସମୟରେ ପ୍ରଚୁର ବର୍ଷା ବା ଆର୍ଦ୍ରତା ଦରକାର, ଏବଂ ଝୋଟ ସଢ଼ାଇ (ରେଟିଂ) ତନ୍ତୁ ବାହାର କରିବା ପାଇଁ ସଫା ପାଣି ଆବଶ୍ୟକ।"
    },
