      "hi": "4-5 सिंचाइयों की आवश्यकता। ताज जड़ जमने (CRI 20-22 दिन) की अवस्था अत्यंत महत्वपूर्ण; इसके बाद कल्ले, फूल और दाना भरने पर पानी दें।",
