      "kn": "4-5 ನೀರಾವರಿಗಳು ಅಗತ್ಯ. ಕಿರೀಟ ಬೇರು ಬಿಡುವ ಹಂತ (CRI 20-22 ದಿನಗಳು) ನಿರ್ಣಾಯಕ; ನಂತರ ಕವಲೊಡೆಯುವಿಕೆ, ಹೂಬಿಡುವಿಕೆ ಮತ್ತು ಕಾಳು ತುಂಬುವಾಗ ನೀರು ನೀಡಿ.",
      "ml": "4-5 നനകൾ ആവശ്യമാണ്. കിരീട വേരുകൾ ഉണ്ടാകുന്ന ഘട്ടം (CRI 20-22 ദിവസം) നിർണായകമാണ്; തുടർന്ന് തൈപൊട്ടൽ, പൂവിടൽ, പാൽ നിറയൽ സമയത്ത് നനയ്ക്കുക.",
      "mr": "4-5 पाण्याच्या पाळ्या आवश्यक. मुकुट मुळे फुटण्याची अवस्था (CRI 20-22 दिवस) अत्यंत संवेदनशील; त्यानंतर फुटवे, फुलोरा व दाणे भरताना पाणी द्या.",
      "bn": "৪-৫টি সেচ প্রয়োজন। মুকুট শিকড় গজানোর পর্যায় (CRI ২০-২২ দিন) অত্যন্ত গুরুত্বপূর্ণ; পরবর্তীতে কুশি, ফুল ও দানা গঠনের সময় সেচ দিন।",
      "gu": "૪-૫ પિયત જરૂરી. મુકુટ મૂળ ફૂટવાનો તબક્કો (CRI ૨૦-૨૨ દિવસ) સૌથી અગત્યનો છે; ત્યારબાદ ફૂટ, ફૂલ અને દાણા ભરાતી વખતે પિયત આપો.",
      "od": "୪-୫ ଥର ଜଳସେଚନ ଦରକାର। ମୁକୁଟ ଚେର ବାହାରିବା (CRI ୨୦-୨୨ ଦିନ) ଅତ୍ୟନ୍ତ ଜରୁରୀ; ପରେ କାଣ୍ଡ, ଫୁଲ ଓ ଦାନା ଭରିବା ବେଳେ ପାଣି ଦିଅନ୍ତୁ।"
