      "kn": "ಚಳಿಗಾಲದ ಮಂಜು ಮುಸುಕಿದ ವಾತಾವರಣದಲ್ಲಿ ಅಂಗಮಾರಿ ರೋಗ (ಲೇಟ್ ಬ್ಲೈಟ್) ತೀವ್ರವಾಗಿ ಬಾಧಿಸುವ ಸಾಧ್ಯತೆ.",
