      "kn": "ದೃಢೀಕೃತ ರೋಗಮುಕ್ತ ಬಿತ್ತನೆ ಗೆಡ್ಡೆಗಳನ್ನು ಬಳಸಿ, ಸಕಾಲದಲ್ಲಿ ಮಣ್ಣು ಏರಿಸುವಿಕೆ (ಅರ್ಥಿಂಗ್-ಅಪ್) ಮಾಡಿ ಮತ್ತು ಮ್ಯಾಂಕೋಜೆಬ್ ಸಿಂಪಡಿಸಿ.",
      "ml": "രോഗമില്ലാത്ത സാക്ഷ്യപ്പെടുത്തിയ വിത്ത് കിഴങ്ങുകൾ ഉപയോഗിക്കുക, യഥാസമയം മണ്ണ് കൂട്ടിക്കൊടുക്കുക, മാങ്കോസെബ് തളിക്കുക.",
