      "gu": "પ્રમાણિત રોગમુક્ત બિયારણ વાપરો, સમયસર ચડાવણી (માટી ચડાવવી) કરો અને મેન્કોઝેબનો છંટકાવ કરો.",
      "od": "ପ୍ରମାଣିତ ରୋଗମୁକ୍ତ ବିହନ ଆଳୁ ବ୍ୟବହାର କରନ୍ତୁ, ଠିକ୍ ସମୟରେ ମୂଳରେ ମାଟି ଦିଅନ୍ତୁ ଏବଂ ମାଙ୍କୋଜେବ୍ ସ୍ପ୍ରେ କରନ୍ତୁ।"
