      "kn": "ಆಳವಿಲ್ಲದ ಬೇರುಗಳಿರುವುದರಿಂದ 8-10 ದಿನಗಳ ಅಂತರದಲ್ಲಿ 6-8 ಲಘು ನೀರಾವರಿ ನೀಡಿ. ಗಿಡ ಕತ್ತರಿಸುವ (ಡಿಹಾಲ್ಮಿಂಗ್) 10 ದಿನಗಳ ಮುನ್ನ ನೀರು ನಿಲ್ಲಿಸಿ.",
      "ml": "ആഴം കുറഞ്ഞ വേരുകളായതിനാൽ 8-10 ദിവസത്തെ ഇടവേളയിൽ 6-8 ലഘു നനകൾ നൽകുക. തണ്ട് മുറിക്കുന്നതിന് 10 ദിവസം മുൻപ് നന നിർത്തുക.",
      "mr": "उथळ मुळे असल्याने 8-10 दिवसांच्या अंतराने 6-8 हलकी पाणी द्यावे. काढणीपूर्वी शेंडे कापण्याच्या (डिहॉल्मिंग) 10 दिवस आधी पाणी बंद करावे.",
      "bn": "অগভীর শিকড়ের কারণে ৮-১০ দিন অন্তর ৬-৮টি হালকা সেচ দিন। ডাল কাটার (ডিহলমিং) ১০ দিন আগে জল দেওয়া বন্ধ করুন।",
      "gu": "છીછરા મૂળ હોવાથી ૮-૧૦ દિવસના અંતરે ૬-૮ હળવા પિયત આપો. વેલા કાપવાના (ડિહોલ્મિંગ) ૧૦ દિવસ પહેલાં પિયત બંધ કરો.",
      "od": "ଅଗଭୀର ଚେର ଯୋଗୁଁ ୮-୧୦ ଦିନ ବ୍ୟବଧାନରେ ୬-୮ ଥର ହାଲୁକା ଜଳସେଚନ କରନ୍ତୁ। ଡାଳ କାଟିବାର ୧୦ ଦିନ ପୂର୍ବରୁ ପାଣି ବନ୍ଦ କରନ୍ତୁ।"
