      "ml": "അത്യന്താപേക്ഷിതമായ അടുക്കള വിഭവം; വിപണിയിൽ എപ്പോഴും വലിയ ഡിമാൻഡും വിലവർദ്ധനവും",
      "mr": "अत्यावश्यक शेतमाल; वर्षभर प्रचंड मागणी आणि हंगामात मिळणारा उच्च बाजारभाव",
      "bn": "নিত্যপ্রয়োজনীয় রান্নাঘরের সামগ্রী; বাজারে স্থায়ী উচ্চ চাহিদা এবং মরশুমে চড়া দাম",
