      "kn": "ಕಪ್ಪು, ಕೆಂಪು ಮತ್ತು ಮೆಕ್ಕಲು ಮಣ್ಣಿಗೆ ಸುಲಭವಾಗಿ ಹೊಂದಿಕೊಳ್ಳುತ್ತದೆ. ಬೀಜಗಳು ಪೂರ್ಣ ತುಂಬಲು ತಟಸ್ಥ pH ಮತ್ತು ಬೋರಾನ್ ಪೋಷಕಾಂಶ ಅಗತ್ಯ.",
      "ml": "കറുത്ത മണ്ണിലും ചുവന്ന മണ്ണിലും എക്കൽ മണ്ണിലും നന്നായി വളരുന്നു. വിത്തുകൾ പൂർണ്ണമായി നിറയാൻ ബോറോൺ ആവശ്യമാണ്.",
