      "bn": "সংকটপূর্ণ পর্যায়: কুঁড়ি গঠন (৩০-৩৫ দিন), ফুল ফোটা (৫০-৫৫ দিন) এবং দানা গঠন (৬৫-৭৫ দিন)। গ্রীষ্মের তাপ ভালো সহ্য করে।",
