      "te": "వర్షాకాలంలో దుంప కుళ్ళు తెగులు (పైథియం) మరియు కాండం తొలుచు పురుగు బెడద.",
      "hi": "मानसून के दौरान कंद सड़न (राइजोम रॉट) और तना छेदक का प्रकोप।",
