      "kn": "ಮಳೆಗಾಲದಲ್ಲಿ ಗೆಡ್ಡೆ ಕೊಳೆ ರೋಗ (ಪೈಥಿಯಂ) ಮತ್ತು ಕಾಂಡ ಕೊರೆಯುವ ಹುಳು.",
      "ml": "കാലവർഷ സമയത്തെ കിഴങ്ങ് ചീയലും തണ്ടുതുരപ്പൻ പുഴുവിന്റെ ആക്രമണവും.",
      "mr": "पावसाळ्यात कंदकूज (पायथियम) आणि खोडकिडीचा प्रादुर्भाव.",
      "bn": "বর্ষাকালে কন্দ পচা রোগ এবং কাণ্ড ছিদ্রকারী পোকার আক্রমণ।",
      "gu": "ચોમાસા દરમિયાન ગાંઠનો સડો (પાયથિયમ) અને સાંઠાની ઈયળનો ઉપદ્રવ.",
      "od": "ବର୍ଷା ଦିନେ କନ୍ଦ ସଢ଼ା ରୋଗ ଏବଂ କାଣ୍ଡ ବିନ୍ଧା ପୋକର ଆଶଙ୍କା।"
