      "hi": "कार्बेंडाजिम उपचारित दो-आंखों वाले टुकड़ों की बुवाई करें, सूखी पत्तियों की मल्चिंग करें और गन्ने की बंधाई करें।",
      "ta": "கார்பெண்டாசிம் நேர்த்தி செய்த இருபருக் கரணைகளை நடவும், கரும்பு தோகையை மூடாக்காக இடவும், கரும்புகளைக் கட்டிவிடவும்.",
