      "gu": "કાર્બેન્ડાઝિમ માવજત કરેલા બે આંખવાળા ટુકડા રોપો, પાંદડાનું મલ્ચિંગ કરો અને શેરડીને ટેકા બાંધો.",
      "od": "କାର୍ବେଣ୍ଡାଜିମ୍ ବିଶୋଧିତ ଦୁଇ ଆଖି ଖଣ୍ଡ ରୋପଣ କରନ୍ତୁ, ଶୁଖିଲା ପତ୍ର ମଲ୍ଚିଂ କରନ୍ତୁ ଏବଂ ଆଖୁକୁ ବାନ୍ଧନ୍ତୁ।"
