      "ml": "കാലവർഷത്തിന് മുൻപ് 1% ബോർഡോ മിശ്രിതം തളിക്കുക, കുലകൾ പോളിത്തീൻ കവറുകൊണ്ട് മൂടുക, ബയോഗ്യാസ് സ്ലറി ഒഴിക്കുക.",
