      "bn": "বর্ষার আগে ১% বোর্দো মিশ্রণ স্প্রে করুন, সুপারি ছড়ায় পলিথিন কভার বাঁধুন এবং বায়ো-ডাইজেস্টার স্লারি দিন।",
      "gu": "ચોમાસા પહેલાં ૧% બોર્ડો મિશ્રણ છાંટો, ઝૂમખાં પર પ્લાસ્ટિક કવર બાંધો અને બાયો-ડાયજેસ્ટર સ્લરી આપો.",
      "od": "ମୌସୁମୀ ପୂର୍ବରୁ ୧% ବୋର୍ଡୋ ମିଶ୍ରଣ ସ୍ପ୍ରେ କରନ୍ତୁ, ଗୁଆ କେଣ୍ଡାରେ ପଲିଥିନ୍ ଘୋଡ଼ାନ୍ତୁ ଏବଂ ଜୈବିକ ସ୍ଲରି ଦିଅନ୍ତୁ।"
